"""Serialize authored dyadic relationship design with explicit privacy limits."""
import json
import re
from pathlib import Path
RUN=Path(__file__).resolve().parent
def refs(*ns): return [f'SRC-{n:03d}' for n in ns]

def build():
    rows=[
      ('vCard Format Specification','IETF','https://www.rfc-editor.org/rfc/rfc6350','RFC6350 August 2011; update audit pending','standard','Selected RELATED property only; not bilateral truth or full current vCard conformance. HEAD unavailable, web text inspected.'),
      ('FHIR RelatedPerson','HL7','https://hl7.org/fhir/R5/relatedperson.html','R5 5.0.0','standard','Selected attribution, relationship period and distinction from Patient.contact; healthcare profile only.'),
      ('Role','schema.org','https://schema.org/Role','Development version inspected 2026-09-09; release pin pending','schema','Qualified roles and periods; not authority or reciprocity.'),
      ('FOAF Vocabulary Specification','FOAF Project','https://xmlns.com/foaf/spec/','0.99, 14 January 2014','ontology','Selected knows semantics do not imply friendship or endorsement; speculative social inference is not adopted.'),
      ('PROV-O: The PROV Ontology','W3C','https://www.w3.org/TR/prov-o/','Recommendation; dated pin pending','ontology','Qualified attribution preserves authorship, not truth, consent or bilateral confirmation.'),
      ('Principle (c): Data minimisation','Information Commissioner Office','https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/data-protection-principles/a-guide-to-the-data-protection-principles/data-minimisation/','Guidance under review after Data (Use and Access) Act','public-authority','Selected minimisation and opinion attribution; UK profile not universal legal advice. HEAD unavailable, text readable.')]
    sources=[dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type=k,primary_source=True,authority_tier=1,accessed_at='2026-09-09T22:37:30Z',relevance=r) for i,(t,o,u,v,k,r) in enumerate(rows,1)]
    ids=['relation-identity','relation-typing','relation-assertion','relation-perspectives','relation-roles','relation-contact-boundaries','relation-shared-context','relation-episodes','relation-disclosure','relation-correction','relation-mapping','relation-acceptance']
    citations=[refs(1,2,5),refs(1,3,4),refs(2,5,6),refs(4,5,6),refs(2,3,6),refs(2,6),refs(4,5,6),refs(2,3,5),refs(5,6),refs(5,6),refs(1,2,3,4,5),refs(1,2,3,4,5,6)]
    kinds=[['identity','relationship','quality'],['classification','relationship','classification'],['provenance','evidence','quality'],['evidence','relationship','exception'],['definition','relationship','constraint'],['constraint','authority','access'],['relationship','evidence','privacy'],['temporal','event','lifecycle'],['authority','privacy','privacy'],['process','retention','lifecycle'],['interoperability','quality','constraint'],['validation','authority','security']]
    bundles=[]; n=0
    for group in re.split(r'(?m)^## ',(RUN/'question-design.md').read_text(encoding='utf-8'))[1:]:
        title=re.sub(r'^\d+\s+','',group.split('\n',1)[0]); layers=[]
        for section in re.split(r'(?m)^### ',group)[1:]:
            heading,body=section.split('\n',1); name=re.sub(r'^\d+\.\d+\s+','',heading)
            qs,answers=body.split('Answer groups:',1)
            questions=re.findall(r'(?m)^\d\. (.+\?)$',qs); groups=re.findall(r'([a-zA-Z]+)\{([^}]+)\}',answers)
            assert len(questions)==len(groups)==3
            lid=ids[n]; sr=citations[n]
            desc='Authored relationship-memory design for '+name.lower()+', qualified by perspective, time and authorized evidence; not a universal interpersonal truth judgment.'
            fields=[dict(id=lid+'-'+key.lower(),name=key,description='Proposed members: '+members+'. Unknowns and author/source scope remain explicit; executable nested schemas are deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr) for key,members in groups]
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr,questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[n][i],answer_data=[fields[i]['id']]) for i,q in enumerate(questions)],data_elements=fields,artifacts=[dict(id=lid+'-evidence',name=name+' evidence record',description='Minimal attributed assertion or protected reference; never bundle private messages or identify a hidden relationship in public filenames.',media_or_form=['text/markdown','application/json','application/yaml','authorized reference'],serial=True,identity_strategy='Master-qualified ID, governed opaque URI or Dimension UUID, with separate immutable revision/digest; not names or timestamp alone.',source_refs=sr)],inline_only_rationale=None)
            finding['artifacts'][0]['id']=lid+'-artifact'
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr,findings=[finding])); n+=1
        assert len(layers)==2
        bundles.append(dict(id='relation-'+re.sub('[^a-z]+','-',title.lower()).strip('-'),name=title,description='Dyadic interpersonal '+title.lower()+'.',rationale='Groups relation-owned context without taking ownership of people, messages, legal status or communication actions.',source_refs=sorted(set(s for l in layers for s in l['source_refs'])),layers=layers))
    assert n==12 and len(bundles)==6
    model=dict(registry_id='vr.wm-per-011',model_id='WM-PER-011',name='Interpersonal Relationship',entry_kind='relationship',purpose='Describe a dyadic interpersonal relationship through independent roles, validity and privacy-aware attributed perspectives.',scope_statement='A relationship between two referenced persons in a governed context, with independently qualified assertions and role episodes; not a global social graph or objective intimacy assessment.',in_scope=['Scoped relationship identity, typed roles, direction and person references','Evidence, competing perspectives, role boundaries and episodes','Purpose-limited record access, correction and loss-aware projection'],out_of_scope=['Person identity masters, multiparty groups and households','Automatic outreach, social trust scoring or sensitive relationship inference','Legal status adjudication, consent grants and private-message ingestion'],boundary_notes=[dict(neighbor=a,distinction=b,source_refs=s) for a,b,s in [('Person','Participants remain references; relationship is not a Person subtype despite registry parent navigation.',refs(1,2,4)),('Contact','Contact detail and RelatedPerson serve different purposes; neither alone grants communication rights.',refs(2,6)),('Legal representation','Role label is not sufficient evidence of mandate or legal rights.',refs(2,3)),('Encounter','Co-occurrence does not establish friendship or intimacy under this conservative profile.',refs(4,5,6)),('Group','Dyadic profile does not represent all multiparty social structures.',refs(1,2,4))]])
    services=dict(
      dimension=dict(owner_package_requirements=['Declare relationship-record steward and participants as distinct roles.','Identify authorized person, assertion and evidence masters.','Bind purpose, access, disclosure, correction and retention policies.'],namespace_guidance='Opaque master-qualified relationship identity; person and assertion identifiers remain separate and never exposed merely through filenames.',registry_links=['Relationship registry','Person references','Assertion/episode registry','Policy and protected evidence references']),
      canon_and_patch=dict(canonicalization_rules=['Preserve endpoint direction, vocabulary and independent author perspectives.','Keep effective episode times separate from observation and recording time.'],patch_rules=['Pin base version/digest; namespace role/profile extensions.','Append expected-head corrections with attributed reason, preserving permitted competing assertions.'],compatibility_rules=['Do not collapse types, inverse roles or episodes without explicit mapping.','Required privacy and perspective loss causes export refusal.']),
      artifact_rules=dict(identity_priority=['Master-qualified opaque identifier','Governed issuer-qualified URI','Dimension-issued UUID'],timestamp_rule='Use RFC 3339 seconds and explicit offset or Z for recording instants; preserve uncertain/date-only effective times separately.',serial_naming_rule='Opaque relationship ID plus record-kind and revision; no private names or sensitive relation labels in paths.',integrity_rule='Verify exact-byte digest and revision; integrity does not prove reciprocity or truth.'),
      policies=['Never infer intimacy, sensitive status or trust from surname, location, messages or a knows edge.','Attribution is not bilateral consent, truth or permission to contact.','Respect the other person and their data policies; owning a local record does not authorize unrestricted disclosure.','Do not collect private material merely to fill optional context.'],
      crud=dict(read=['Read owning Dimension policy, authorized scope, pinned spec and assurance before participant references.'],create=['Record an authorized attributed claim with endpoint ambiguity and unknowns explicit.'],update=['Append perspective or episode corrections under expected-head checks; do not silently resolve disagreement.'],delete=['Apply justified retention, erasure and legal-hold policy; keep only permitted minimal tombstones, not sensitive erased content.']),
      roles=[dict(name=a,responsibilities=[b]) for a,b in [('Dimension owner','Delegates local memory scope, not ownership of another person.'),('Relationship steward','Maintains qualified relation and episode records.'),('Contributor','Supplies authorized attributed assertions.'),('Reviewer','Checks perspective, direction and evidence limits.'),('Custodian','Enforces restricted access and retention.')]],
      access=dict(default_rule='Deny absent field- and purpose-specific authority; even relationship existence may be restricted.',scopes=['bundle','layer','finding','artifact'],exceptions=['Only explicit scoped time-limited disclosure exceptions with authorizer and rationale.'],audit_requirements=['Log authorized operation and opaque record/revision references without exposing sensitive content or credentials.']),
      agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension purpose and privacy policy','Pinned spec and participant/reference authority','Attributed perspectives, role episodes and evidence','Validation, patching, record operations and safe retirement']))
    frows=[('resolve-relationship','Resolve relationship',['Scoped ID and endpoint candidates'],['Reference or ambiguity'],['Read authority','No name-only merge'],['Read-only, no identity merge'],refs(1,2,5)),('append-relation-assertion','Append attributed assertion',['Claim and author','Minimal source refs','Expected head'],['New claim revision'],['Write authority','Data purpose justified'],['No social fact or bilateral recognition conferred'],refs(2,5,6)),('record-perspective','Record participant perspective',['Attributable statement','Claim refs','Evidence limits'],['Independent perspective or dispute'],['Authorized source','No forced reconciliation'],['No contacting participant or inferred consent'],refs(4,5,6)),('link-relation-context','Link context evidence',['Authorized event/activity refs','Source and period'],['Qualified links'],['Reference access','Minimization checked'],['No message ingestion or intimacy inference'],refs(4,5,6)),('record-relation-episode','Record episode change',['Role interval','Attributed transition evidence','Expected head'],['Episode revision or uncertainty'],['Write scope','Effective precision preserved'],['No declaration that all social ties ended'],refs(2,3,5)),('export-relation-projection','Export minimized projection',['Allowed fields','Target profile/version','Loss rules'],['Projection or refusal'],['Disclosure authority','Required qualifiers preserved'],['No public release or outreach without authority'],refs(1,2,3,4,6))]
    functions=[dict(id=i,name=n,description='Proposed record operation: '+n.lower()+'. Not an implemented social-action engine.',inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,a,b,c,e,s in frows]
    composition=[dict(target=t,relation=r,purpose=p,required=False,source_refs=s) for t,r,p,s in [('WM-PER-001','REFERENCE','Candidate participant reference, never Person inheritance or ownership.',refs(1,2,4)),(rows[0][2],'ALIGN','Selected RELATED fields with loss annotations.',refs(1)),(rows[1][2],'ALIGN','Limited patient-context mapping; not full RelatedPerson payload ownership.',refs(2)),(rows[2][2],'ALIGN','Qualified role mapping, development-version hold.',refs(3)),(rows[3][2],'ALIGN','Only appropriate knows semantics, never all relationships.',refs(4)),(rows[4][2],'ALIGN','Assertion attribution, not truth or consent.',refs(5))]]
    dims=[('identity','Scoped relation and separate endpoint identities.'),('classification','Role vocabulary, direction and cultural label context.'),('direct properties','Type, perspective and validity rather than physical measures.'),('recognition','Attributed statements and evidence without sensitive inference.'),('capabilities','Six bounded record operations.'),('lifecycle','Role episodes, corrections and retirement.'),('relationships','Persons, encounters and mandates are references.'),('temporal','Effective and recorded times kept distinct.'),('provenance','Claim authors and evidence scope retained.'),('ownership','Record stewardship does not own participants.'),('access','Relationship existence and details purpose-gated.'),('retention','Policy-aware erasure and minimal tombstones.'),('interoperability','Required qualifier loss blocks export.')]
    coverage=dict(claim='Bounded dyadic relationship-memory draft, not universal sociology, legal judgment or independent review.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='validation',status='gap',notes='Executable nested schemas and privacy/reciprocity/round-trip fixtures not implemented.'),dict(dimension='physical properties',status='not-applicable',notes='Physical features belong to referenced persons or places.')],known_omissions=['Claude and Grok each timed out once; no independent external review.','Selected clauses only; RFC updates/errata, dated pins and licenses pending.','schema.org development version and ICO under-review guidance need stable profile verification.','RFC and ICO HEAD unavailable despite readable text.','No universal social/kinship taxonomy, multiparty profile or sensitive-inference mechanism.','No executable nested schemas, reciprocity/privacy fixtures or ratified composition adapters.'],conflicts=[],regional_assumptions=['FHIR healthcare and ICO UK guidance are bounded examples; role meanings vary by vocabulary and culture.'],adversarial_checks=['One-sided report is not reciprocity.','knows is not endorsement or intimacy.','Social role is not a mandate or contact permission.','Shared context does not authorize sensitive inference.','Ending an episode does not end every tie.','Tombstones cannot disclose erased private details.','No private person records were accessed for this specification.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
